      "Տոլման կը սահմանուի ձեւով եւ ոչ թէ բաղադրատոմսով. բրինձը, սոխն ու առատ կանաչեղէնը՝ աղացած գառնուկի կամ արջառի միսով կամ առանց անոր, կը փաթթուին որթատունկի կամ կաղամբի տերեւի մէջ կամ կը լեցուին պարպուած պղպեղի, սմբուկի, լոլիկի ու սերկեւիլի մէջ, ապա խիտ կը շարուին կաթսայի մը մէջ, կը ծանրանան եւ դանդաղ կ՚եփին։ Անունը կը ծագի թիւրքական բայէ մը՝ «լեցուիլ» իմաստով։ Անմիս տարբերակը՝ պասուց տոլման, կը պատրաստուի լուբիայով, սիսեռով, ոսպով ու հատիկեղէնով, կը մատուցուի պաղ եւ կը պատկանի եկեղեցական պահքի օրերուն։ Հայկական տուներուն մէջ ան հաւաքոյթներու կերակուր է եւ ոչ թէ առօրեայ ճաշ, եւ հարիւրաւոր տերեւ փաթթելը հաւաքական աշխատանք է։ Ձեւը հին է եւ տարածուած ամբողջ տարածաշրջանին մէջ՝ ազգակից անուններով. ԵՈՒՆԵՍՔՕ-ի 2017-ի ընդգրկումը ըրած է Ազրպէյճանը եւ կ՚արձանագրէ կենդանի աւանդութիւն մը, ոչ թէ ծագում մը։",
    intro:
      "Տոլման բրինձի, սոխի, կանաչեղէնի եւ յաճախ աղացած միսի լեցոն մըն է, որ կը փաթթուի տերեւներու մէջ կամ կը լեցուի պարպուած բանջարեղէնի մէջ եւ դանդաղ կ՚եփուի։ Ան կը պատրաստուի ամբողջ Կովկասի, Անատոլիոյ, Իրանի եւ Արեւելեան Միջերկրականի մէջ՝ նոյն բայէն ծագող անուններով։ Հայկական տուներուն մէջ ան հաւաքոյթներու կերակուր է եւ ոչ թէ առօրեայ արագ ճաշ, եւ ունի անմիս տարբերակ մը՝ պահքի համար։ 2017 թուականին ԵՈՒՆԵՍՔՕ ներկայացուցչական ցանկին մէջ ընդգրկեց տոլմա պատրաստելու աւանդութիւնը. այդ ներկայացումը ըրած է Ազրպէյճանը, եւ իրողութիւնը հոս կը նշուի եւ ոչ թէ կը շրջանցուի, որովհետեւ այդ ընդգրկումին ընթերցումը ինք այս կերակուրին պատմութեան մասն է։",
