    excerpt:
      "Բաց կրակի կարմրած ածուխներուն վրայ խորոված միս եւ անոր շուրջ կազմուող ընկերային առիթը. ո՛վ կը վառէ կրակը, ո՛վ կը հսկէ զայն, եւ ինչո՛վ կը տարբերի ան մատաղի հաւաքական ճաշէն։",
    metaDescription:
      "Խորովածը՝ կարմրած ածուխներու վրայ խորոված միս. ինչ կը նշանակէ բառը, ինչպէս կը վարուի կրակը, խորովածի աղցանը եւ ինչո՛վ կը տարբերի մատաղէն։",
    summary:
      "Խորովածը բաց կրակի վրայ եփուող միս է. բառը «խորովել» բային ձեւն է եւ կ՚անուանէ ձեւը, ոչ թէ որեւէ մէկ բաղադրատոմս։ Խոզի, գառնուկի, արջառի կամ հաւու խոշոր կտորները կ՚աղուին եւ կը ձգուին սոխի ու կանաչեղէնի հետ, ապա կը շարուին երկար, հարթ շամփուրներու վրայ եւ կ՚եփին կարմրած ածուխներու եւ ոչ թէ բոցի վրայ. համեմը միտումնաւոր զուսպ է, որովհետեւ կերակուրին իմաստը կրակն է։ Քովը կը խորովուին սմբուկ, պղպեղ ու լոլիկ, որոնք կը մաքրուին ու կը մանրուին առանձին կերակուրի մը՝ խորովածի աղցանին մէջ, իսկ միսը յաճախ ուղիղ շամփուրէն կը սահի լաւաշին վրայ։ Առիթը պակաս կարեւոր չէ քան կերակուրը՝ բացօթեայ վառուած կրակ մը եւ անոր շուրջ անցուցած կէսօր մը։ Սփիւռքին մէջ ան ամուր պահպանուած է, որովհետեւ թոնիր չի պահանջեր։ Ան մատաղը չէ՝ նուիրուած ու բաժնուած անասունի հաւաքական ճաշը, թէեւ երկուքը ընդհանուր ձեւ մը ունին։",
    intro:
      "Խորովածը բաց կրակի վրայ եփուող միս է. բառը ինք «խորովել» բային ձեւն է եւ կ՚անուանէ ձեւը, ոչ թէ որեւէ մէկ բաղադրատոմս։ Գործնականօրէն ան նաեւ առիթ մըն է. բացօթեայ վառուած կրակ մը, մէկը՝ շամփուրներուն քով, միւս բոլորը՝ սպասումի մէջ, եւ սեղան մը՝ որ կը կազմուի կրակէն իջածին շուրջ։ Ան այն կերակուրներէն է՝ որ Սմիթսոնեան ժողովրդական մշակոյթի փառատօնը 2018 թուականին ներկայացուց իբրեւ հայկական խնճոյքի հիմնական կերակուր, եւ կը կենայ մատաղին՝ միսի հին հաւաքական ճաշին քով, բայց նոյն բանը չէ։",
