    excerpt:
      "Ցորեն եւ միս՝ որոնք ժամերով կը խառնուին մինչեւ մէկ նիւթ դառնան. կերակուր մը՝ արձանագրուած Պաղտատի տասներորդ դարու խոհարարական ժողովածուի մը մէջ, եւ որուն շուրջ ամէն Սեպտեմբեր կը յիշատակուի Մուսա լերան դիմադրութիւնը։",
    metaDescription:
      "Հարիսան՝ մաքրուած ցորենէ ու միսէ ժամերով խառնուող կերակուրը. Պաղտատի տասներորդ դարու գրաւոր վկայութիւնը եւ Մուսալեռի սեպտեմբերեան յիշատակումը։",
    summary:
      "Հարիսան մաքրուած ցորենէ՝ հայերէն կորկոտէ, եւ հաւու կամ գառնուկի միսէ կը պատրաստուի, որոնք ժամերով կ՚եփին ու կը խառնուին այնքան՝ մինչեւ միսը լիովին քայքայուի, ցորենը բացուի, եւ կերակուրը դառնայ մէկ միասնական թանձր զանգուած եւ ոչ թէ կտորներով ապուր։ Խտութիւնը անոր փորձն է. ճիշդ պատրաստուածը մէկ ամբողջութեամբ կը պոկուի դգալէն։ Մատուցելէ առաջ վրան կը թափուի հալած կարագ, իսկ քիմիոնը կամ պղպեղը կ՚առաջարկուի առանձին։ Ան շատ քիչէ կը կերակրէ շատ մարդ, եւ ճիշդ ասոր համար կը պատկանի հաւաքական ու եկեղեցական առիթներու եւ ոչ թէ մէկ ընտանիքի սեղանին։ Անոր գրաւոր պատմութիւնը կը հասնի Պաղտատի տասներորդ դարու խոհարարական ժողովածուին, եւ ազգակից անուններով տարբերակներ կը պատրաստուին ամբողջ Միջին Արեւելքին մէջ։ Անոր ամէնէն ծանօթ հայկական առիթը շատ աւելի նոր է՝ Արմաւիրի Մուսալեռի մէջ 1915-ի Մուսա լերան դիմադրութեան սեպտեմբերեան յիշատակումը։",
    intro:
      "Հարիսան մաքրուած ցորենէ եւ միսէ կը պատրաստուի, որոնք միասին կ՚եփին ժամերով եւ կը խառնուին այնքան՝ մինչեւ մէկը միւսէն չզանազանուի։ Ան նուրբ կերակուր չէ եւ բնաւ ալ այդպիսին ըլլալու նախատեսուած չէ. շատ քիչ բանէ կը կերակրէ շատ մարդ, եւ մեծ կաթսայի մը մէջ կրնայ շարունակուիլ ամբողջ գիշեր։ Անոր գրաւոր պատմութիւնը կը հասնի Պաղտատի տասներորդ դարու խոհարարական ժողովածուին, ուր հարիսան կ՚երեւի իբրեւ ծեծուած ցորենի ու միսի կերակուր։ Անոր ամէնէն ծանօթ հայկական առիթը շատ աւելի նոր է՝ Արմաւիրի Մուսալեռ գիւղին մէջ ամէն Սեպտեմբեր կատարուող յիշատակումը՝ 1915 թուականի Մուսա լերան դիմադրութեան։",
