      "Գաթան անուշ թխուածք մըն է, որուն լեցոնը սեփական անուն ունի՝ խորիզ. կարագի ու շաքարի մէջ շփուած ալիւր, որ փշրանքով կը պահուի եւ թխուելու ատեն ետ կը հալի խմորին մէջ։ Խմորը կարագով կը հարստացուի, յաճախ նաեւ մածունով կամ թթուասերով, իսկ վերը թխելէ առաջ ձուով կը քսուի ու կը նախշուի. զարդարանքը միաժամանակ կ՚արգիլէ որ մակերեսը ուռի։ Արդիւնքը խոնաւ չէ այլ չոր, եւ ճիշդ ասիկա է որ գաթային կ՚արտօնէ պահուիլ ու ճամբայ երթալ. ամբողջական, փաթթուած գաթան այցելութեան սովորական նուէրն է, իսկ վանքերու դռներուն քով ծախուող նախշուած շրջանները շատերու յիշողութեան մէջ գաթային գլխաւոր տեսքն են։ Մնացեալ գրեթէ ամէն բան փոփոխական է. չափերը՝ սեղանի լայնութեամբ շրջանէն մինչեւ ափի մը մէջ տեղաւորուող գլանիկ, ընտանիքներէն շատեր կը պահեն իրենց նախշը, իսկ ընկոյզով տարբերակը՝ որ կը պատրաստուի հարաւին եւ Իրանի հայերուն մօտ, յաճախ նազուկ կը կոչուի։",
    intro:
      "Գաթան անուշ խմորեղէն մըն է՝ սեփական անուն ունեցող լեցոնով. խորիզ, այսինքն՝ կարագի ու շաքարի մէջ շփուած ալիւր, որ թխուելու ատեն ետ կը հալի խմորին մէջ։ Անկէ անդին գրեթէ ամէն բան փոփոխական է։ Գաթան կրնայ ըլլալ սեղանի լայնութեամբ շրջան մը կամ ափի մը մէջ տեղաւորուող գլանիկ, կրնայ ըլլալ հարթ կամ խիտ նախշուած, կրնայ ըլլալ տօնական խմորեղէն, այցելութեան նուէր, կամ կէսօրուան սուրճին քովի բանը։ Ան այն անուշեղէններուն շարքին էր՝ որոնք ցուցադրուեցան Սմիթսոնեան ժողովրդական մշակոյթի փառատօնին հայկական ծրագրին մէջ 2018 թուականին։",
